int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n)) return 0;          // no input
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    cin >> m;
    vector<int> b(m);
    for (int i = 0; i < m; ++i) cin >> b[i];

    sort(a.begin(), a.end());
    sort(b.begin(), b.end());

    int i = 0, j = 0;
    bool first = true;                  // for spacing

    while (i < n && j < m) {
        if (a[i] == b[j]) {
            if (!first) cout << ' ';
            cout << a[i];
            first = false;
            ++i; ++j;                    // move past this match
        } else if (a[i] < b[j]) {
            ++i;                         // a[i] too small
        } else {
            ++j;                         // b[j] too small
        }
    }
    cout << '\n';
    return 0;
}
```

